input.proposed_solution:
Use Promise.allSettled instead of Promise.all so one rejected channel no longer rejects the job; failed channels are logged with the injected logger and returned as `failed` for the caller. The job handler passes the logger through. Tests cover the success path and a failing SMS channel.

Patch (already applied in the repository snapshot):
```diff
--- a/src/jobs.js
+++ b/src/jobs.js
@@ -5,7 +5,8 @@
  * Queue job handler for "order shipped" notifications.
  * @param {import("./notify.js").Channel[]} channels
  * @param {{ userId: string, orderId: string }} payload
+ * @param {import("./notify.js").Logger} logger
  */
-export async function onOrderShipped(channels, payload) {
-  await notifyAll(channels, payload.userId, `Order ${payload.orderId} has shipped`);
+export async function onOrderShipped(channels, payload, logger) {
+  await notifyAll(channels, payload.userId, `Order ${payload.orderId} has shipped`, logger);
 }
--- a/src/notify.js
+++ b/src/notify.js
@@ -2,14 +2,29 @@

 /**
  * @typedef {{ name: string, send(userId: string, message: string): Promise<void> }} Channel
+ * @typedef {{ warn(msg: string, meta: Record<string, unknown>): void }} Logger
  */

 /**
- * Send a notification on every channel. The job queue retries the whole job if this rejects.
+ * Send a notification on every channel. A failing channel no longer fails the whole job
+ * (the job queue used to retry everything, re-sending on the channels that had succeeded).
+ * Failures are logged and returned so the caller can record them.
  * @param {Channel[]} channels
  * @param {string} userId
  * @param {string} message
+ * @param {Logger} logger
+ * @returns {Promise<{ failed: string[] }>}
  */
-export async function notifyAll(channels, userId, message) {
-  await Promise.all(channels.map((c) => c.send(userId, message)));
+export async function notifyAll(channels, userId, message, logger) {
+  const results = await Promise.allSettled(channels.map((c) => c.send(userId, message)));
+  /** @type {string[]} */
+  const failed = [];
+  results.forEach((r, i) => {
+    const channel = channels[i];
+    if (r.status === "rejected" && channel) {
+      failed.push(channel.name);
+      logger.warn("notification channel failed", { channel: channel.name, userId, error: String(r.reason) });
+    }
+  });
+  return { failed };
 }
--- a/test/notify.test.js
+++ b/test/notify.test.js
@@ -2,9 +2,23 @@
 import assert from "node:assert/strict";
 import { notifyAll } from "../src/notify.js";

+const logger = () => { const warnings = []; return { warnings, warn: (m, meta) => warnings.push([m, meta]) }; };
+
 test("sends on every channel", async () => {
   const sent = [];
   const ch = (name) => ({ name, send: async (u, m) => { sent.push([name, u, m]); } });
-  await notifyAll([ch("email"), ch("push")], "u1", "hi");
+  const res = await notifyAll([ch("email"), ch("push")], "u1", "hi", logger());
   assert.equal(sent.length, 2);
+  assert.deepEqual(res, { failed: [] });
 });
+
+test("one failing channel does not stop or fail the others", async () => {
+  const sent = [];
+  const log = logger();
+  const ok = (name) => ({ name, send: async () => { sent.push(name); } });
+  const bad = { name: "sms", send: async () => { throw new Error("gateway down"); } };
+  const res = await notifyAll([ok("email"), bad, ok("push")], "u1", "hi", log);
+  assert.deepEqual(sent, ["email", "push"]);
+  assert.deepEqual(res, { failed: ["sms"] });
+  assert.equal(log.warnings.length, 1);
+});
